"""Assemble original RF source candidates. This is not an engine/test/human-signoff run."""
from pathlib import Path
import json, hashlib, re

HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[2]
VERSION="rf-author-candidate-1"
SOURCES=["docs/baseline/World_Story_Bible_v0.1.md:637-684,856-945", "docs/baseline/Exploration_Level_Design_v0.1.md:569-599", "docs/baseline/Quest_Event_System_v0.1.md:852-856", "docs/baseline/Combat_System_v0.1.md:312-365", "docs/baseline/English_Learning_System_v0.1.md:806-810", "docs/baseline/Puzzle_System_v0.1.md:758-762", "content/source/part04.json:Q-F01..Q-F05", "content/source/part07.json:Q-F01..Q-F05", "content/source/part08.json:ENC-RF-01..04/core", "content/source/part09.json:Q-F reaction bindings"]
MATERIALS=[]
def material(mid,title,q,kind,spot,root,pairs,access="public"):
    paragraphs=[dict(id=f"{mid}-p{i:02}",en=en.strip(),zh=zh.strip()) for i,(en,zh) in enumerate(pairs,1)]
    words=sum(len(re.findall(r"[A-Za-z0-9]+(?:['’-][A-Za-z0-9]+)*",p["en"])) for p in paragraphs)
    m=dict(id=mid,content_version=VERSION,translation_version=VERSION+"-zh",title_zh=title,quest_ref=q,kind=kind,location=dict(scene=spot.split('.')[0],spot=spot),source_root=root,access_class=access,review_status="original_unreviewed",human_review="human_pending",target_band=6.5,calibration_status="human_pending_not_a_score",rights_status="original_text_candidate_human_pending",source_refs=SOURCES,paragraphs=paragraphs,english_word_count=words,audio_asset="")
    if kind=="listening_script":m.update(audio_status="not_recorded",actual_duration_seconds=None,voice_performer="human_pending",performance_and_voice_rights="human_pending",planned_rate_wpm=[140,175],estimated_duration_seconds_range=[round(words*60/175),round(words*60/140)],duration_status="word_count_estimate_not_measured_audio",listening_experience_status="script_only")
    MATERIALS.append(m)

material("RF-QF01-R-SCOPE","登陆范围与准备封存","Q-F01","mission_document","RF-S01.scope","rf-landing-receiving-desk",[
("This landing receives the vessel and the preparation sealed before departure. Match the vessel instance, checkpoint reference and current assignment to the actual arrival receipt. The receiving work concerns entry to the seventh tower and a bounded intervention in its dangerous programme. It does not select a permanent policy. Keep the six districts' preparation records attached; a local officer cannot replace a district's operator or representative signature.","此登陆台接收船与出发前封存的准备。请按实际抵达回执核对船实例、检查点与当前任务。本次接收涉及进入第七塔及对危险程序的有限处置，没有选定永久政策。六地准备记录随附，本地值守不能替代某地区操作方或代表的签字。"),
("The formal passage and maintenance shaft meet at the takeover floor. A recognised temporary authorisation can change how you reach it, but it cannot settle the machine's operating condition. If a formal handover is unavailable, inspect the basic maintenance path. Access must not depend on expressing support for a faction, an English grade, or having recruited a particular companion. External travel remains suspended during this intervention.","正式通道和检修竖井在接管层汇合。获认可的临时授权可改变进入方法，不能裁定机器状态。正式交接暂不可用时，请查基础检修路径。进入不能取决于阵营立场、英语分数或某位同伴是否招募。本次处置期间暂停外区旅行。")])
material("RF-QF01-R-ROUTES","两个入口，同一接管层","Q-F01","short_notice","RF-S01.routes","rf-landing-route-plate",[
("Route F leads through the duty desk and formal corridor. The desk first checks the intervention's actual authorisation; the corridor stop must then be released at its own terminal. Route M uses the maintenance shaft, its installed handle and a checked return path. A coil sentry still controls the lower approach. Neither route leads straight to the dispatch console.","F路经值守台与正式走廊，值守先核实际处置授权，走廊阻拦再由本地终端解除。M路经检修竖井、固定手柄与已查返程，下段仍有线圈哨卫。两路均不能直达调度台。"),
("The local devices are different objects. A corridor release is not the command relay at the takeover floor. A shaft isolation is not the central machine's restart bypass. Follow the labels and keep the completed result of each operation. Retracing a safe route does not collect another reward or refill the same battle attempt.","这些是不同实体。走廊放行不是接管层指挥转接，竖井隔离也不是机组续启旁路。请按标牌保存每个操作结果。回走安全路线不会再发奖励，也不会回满同一战斗尝试。")])
material("RF-QF01-R-CHECKPOINT","出发前存档的用途","Q-F01","short_notice","RF-S01.checkpoint","rf-checkpoint-index",[
("The protected pre-final checkpoint belongs to the actual sealed preparation and departure. Register its reference at the landing desk, without replacing it with an empty save made after arrival. Inside the tower, encounter retries restore their declared entry state and retain source-reading and draft history. They do not reopen regional shipping or rewrite an earlier ending snapshot.","受保护终局前检查点对应实际封存准备与出发。在登陆台登记索引，不能以抵达后空白保存替代。塔内重试按遭遇入口恢复，保留材料接触与草稿历史，没有重开地区航运，也没有改写较早结局快照。")])
material("RF-QF01-L-DUTY","值守联络脚本：确认进入对象","Q-F01","listening_script","RF-S02.call","rf-formal-duty-desk-exchange",[
("Duty officer: Before we release the corridor, please identify the vessel and the scope of this visit. I can receive the temporary intervention authorisation and its actual preparation references. I cannot sign for all six districts or choose what they should operate after the dangerous programme is stopped. The corridor release covers this passage only. It is not an instruction to disconnect the city's rescue communication.","值守：放开走廊前，请确认船和本次范围。我可接收临时处置授权及实际准备索引，不能代六地签字，也不能决定停止危险程序后的运行安排。走廊放行仅覆盖这条通道，不是断开城市救援通信的命令。"),
("Visitor: We will register the checkpoint and keep the source references. If the corridor cannot be accepted now, we will check the maintenance shaft rather than insist that a political preference opens the door. That route still requires its own physical checks. Reaching the takeover floor will establish our approach; it will not establish that Rook's command relay is released or that the central loop has stopped.","访客：我们登记检查点并保留来源索引。走廊暂不接受时，就核验检修竖井，而不要求政治偏好开门。另路仍需实体检查。到接管层只建立接近结果，没有证明鲁克转接已解除或中央循环已停。"),
("Duty officer: Use the installed terminal after the handover is recognised. If a displayed condition changes, stop and check that condition again. You can revise your short entry message before submitting it. A translator or a structured confirmation may help us identify the intended action; neither reports that your free English has been independently assessed. This is a written transcript until an actual recording is played through its separate audio entry.","值守：交接获认可后再使用固定终端。显示条件改变，就停下重查该条件。提交前可改短联络稿。译文或结构化确认可帮助明确动作，两者都没有声称自由英文已独立评估。这是书面脚本，听力需从另一个音轨入口实际播放。")])
material("RF-QF01-R-AUTHORITY","正式通道的临时授权范围","Q-F01","mission_document","RF-S01.scope","rf-formal-authorisation-register",[
("The desk recognises the sealed intervention after matching its actual departure and preparation. The receiving scope is entry, the release of the local command chain, and safe intervention in the central programme. Recognition must be recorded here. Possessing a copy of this description is not the same as an accepted handover. The desk may also record that formal entry is unavailable, leaving the maintenance path usable.","值守台匹配实际出发与准备后，认可封存处置。接收范围为进入、解除本地指挥链及安全处置中央程序，须在此实际登记。持有这份说明副本不等于交接已接受。台可明确记录正式入口不可用，同时保留检修路径。"),
("The recognition grants no private historical fields and no permanent authority over district maintenance. An accepted corridor handover prevents an unnecessary entry alarm; it does not remove Rook's guards, complete relay isolation, or stop the machine. Those domains keep separate results.","认可不授私人历史字段，也不授地区维护永久权力。走廊交接可避免多余接近警报，没有移除鲁克护卫、完成继电隔离或停止机组。各领域分别保存结果。")])
material("RF-QF01-R-CORRIDOR","走廊阻拦终端","Q-F01","short_notice","RF-S02.terminal","rf-corridor-local-controller",[
("Release COR-F only after this desk's recognised temporary handover is current. Check the local interlock and return passage before opening it. A release appears in the corridor status and permits passage to the takeover floor. It gives no instruction to the separate command relays or rescue network. If an interlock changes before confirmation, the earlier preview must be checked again.","仅在本站临时交接当前获认可后解除COR-F。开放前核本地联锁及返程。放行写入走廊状态，允许到接管层，对独立指挥转接或救援网络没有指令。确认前联锁变更，需重查旧预览。")])
material("RF-QF01-R-SHAFT","检修竖井：基础操作与工具替代","Q-F01","procedure","RF-S03.manual","rf-shaft-installed-maintenance-manual",[
("The shaft's ordinary maintenance handle is installed at the marked stand. Inspect its coupling and the return landing, then secure the handle before approaching the lower coil sentry. A folding lever may provide a declared alternate grip; the ordinary handle and careful cooperation remain available. A route reel can mark a checked return anchor, but it does not reveal an unknown passage or make an unsafe floor safe.","竖井常规手柄固定在标记站位。先查连接与返程落台，再固定手柄，随后接近下段线圈哨卫。折叠撬柄可提供声明的替代握点，普通手柄和协作仍可用。路径绳盘可标已查返程锚点，不能发现未知通道或使危险地面安全。"),
("Do not isolate every labelled circuit. Use SH-M, the shaft approach circuit, and check the local indicator after the sentry has been controlled. The action does not isolate the central machine's left and right branches. Keep the shaft result when moving back to the landing; it is a completed local operation rather than a universal tower permission.","不能隔离每个带标牌回路。使用SH-M竖井接近回路，制止哨卫后查本地指示器。这动作没有隔离机组左右支路。返回登陆时保留竖井结果，它是完成的本地操作，而非全塔通行权。")])
material("RF-QF01-R-COIL","SH-M隔离与检查牌","Q-F01","short_notice","RF-S03.coil","rf-shaft-coil-local-plate",[
("SH-M serves the lower shaft approach. Control the coil sentry, isolate SH-M at this stand, inspect the indicator and verify the physical return path. All four results belong to the maintenance approach. Reading this plate or selecting a method does not produce the controlled-sentry result. Control does not award kill experience.","SH-M仅服务竖井下段接近区。先制止线圈哨卫，再在本站隔离SH-M、检查指示并核实体返程。四结果属于检修接近。读牌或选方法不会产生制止结果，制止不发击杀经验。")])
material("RF-QF02-R-COMMAND","两处作战转接与救援联络","Q-F02","mission_document","RF-S04.command","rf-takeover-command-schematic",[
("CMD-L and CMD-R carry Rook's local combat orders at the takeover floor. Shut each named transfer point, then control Rook and the two guards. These points do not carry the city's rescue communication. The left point is reachable from the front-left ally station; the right point from front-right. Each operation costs one action point and occupies that actor's control allowance for the current personal turn.","CMD-L与CMD-R传递接管层鲁克本地作战命令。分别关闭标明转接点，再制止鲁克和两护卫。这两点不承载城市救援联络。左点由友方前左站位操作，右点由前右操作，各耗1AP并占本角色当前个人回合控制额度。"),
("Until both points are confirmed closed, force can reduce resistance but cannot bypass the remaining command chain. The combined attack announces its participants and targets. Controlling a named guard removes only that guard's announced contribution. A stability break on Rook weakens his next attack and cancels the current interruptible combination; it does not remove a complete boss stage or trigger an unannounced substitute attack.","两点未共同确认关闭前，打击可降抵抗，不能跳过残余指挥链。合击公布参与者和目标，制止某护卫仅移除其已声明部分。鲁克失衡减弱下次攻击并取消当前可中断合击，没有删除整段首领阶段，也不触发未公布替补攻击。"),
("The controlled result places Rook under custody and releases his command authority. It does not kill him or settle a different historical dispute. The running machine must still be examined independently. Use the safe preparation stand after the command encounter; the machine's internal stages later share one attempt and do not have this refill boundary.","制止结果把鲁克置于看管并解除指挥权，没有杀死他或裁定别的历史争议。仍运行机组需独立检查。指挥遭遇后可用安全整备站；后续机组内部各阶段共用一次尝试，没有这个回满边界。")])
material("RF-QF02-L-ROOK","接管层现场通信脚本","Q-F02","listening_script","RF-S04.rook","rf-rook-onsite-command-exchange",[
("Rook: This floor has two combat transfer points. They are local to my command chain. Do not pretend that taking them down is the same as operating the city network. My guards will act with me when the combined intention is declared. You can see which guard participates and who is targeted before choosing your response. There will be no replacement strike from a guard whose participation was already removed.","鲁克：本层有两个作战转接点，属于我的本地指挥链。别把关闭它们等同于操作城市网络。合击意图公布时，护卫会参与；你在选择回应前可看到谁参与、目标是谁。已经移除参与的护卫不会再补一次替代攻击。"),
("Receiving officer: Control and custody remain separate from the historical archive. The reviewed records from the old capital remain unchanged by this confrontation. We will record that Rook's command authority is released when the actual points and combat condition are met. We will not record that the central machinery has stopped merely because a person has been restrained. Its indicator is still visible from the audit stand.","接收值守：制止与看管和历史档案分开。旧都已审记录不会因这次对峙改变。实际转接和战斗条件成立后，登记鲁克指挥权解除；不会因一人受约束就登记中央机组停止。核验台仍能看到机组指示。"),
("Rook: A warning is not a cancellation instruction. The maintained loop has its own fixed clauses and physical inertia. You will need the restart log and the local control instructions. If you choose the formal corridor or the shaft, this condition is the same. Receiving officer: We will keep that attributed statement with the independent indicator record. Neither speaker supplies all missing facts simply by appearing in this exchange.","鲁克：警告不是取消指令，维护循环有固化条款及硬件惯性。你还需续启日志与本地操作说明。无论经正式走廊或竖井，这条件相同。接收值守：此说法注明发言者，与独立指示记录并存。两位说话者都不会仅因参与对话而提供全部缺失事实。")])
material("RF-QF02-R-AUDIT","独立状态：指挥解除后程序仍运行","Q-F02","short_notice","RF-S04.audit","rf-takeover-independent-indicator",[
("The local audit indicator distinguishes CMD-L / CMD-R from the maintained central loop. Closing both command points releases the combat chain. The loop's current status must still be read after the encounter. A custody receipt is evidence about a person's command authority; it is not a measurement of the machine. Preserve both records without changing earlier evidence.","本地核验指示区分CMD-L/R与中央维护循环。两转接关闭解除作战链，遭遇后仍需实际读循环当前状态。看管回执证明人物指挥权限，不是机器测量。两记录并存，不改较早证据。")])
material("RF-QF03-R-RESTART","自动续启日志与本段隔离","Q-F03","mission_document","RF-S05.log","rf-central-restart-instrument-log",[
("The maintained programme repeatedly reconnects after an ordinary stop request. Its behaviour comes from conflicting fixed safety clauses, raised thresholds and remaining hardware motion, rather than a new intention or personality. The log records the sequence, not a permission to destroy the installation. Keep the danger loop separate from the policy that the dispatch desk will later execute.","维护程序收到普通停止请求后反复重连。行为来自冲突的固化安全条款、提高的阈值及硬件运动惯性，并非新产生的意图或人格。日志记录顺序，没有许可破坏设施。危险循环与以后调度台执行的政策分开。"),
("At the relay isolation layer, control the field projector before isolating the two local feed selectors. Check this layer's current indicators after both selectors are placed. This establishes safe access to the machine hall. It does not perform the hall's separate branch verification, disable its two internal renewal components, or authorise controlled stop. Configuration changes invalidate the check for the changed object.","继电隔离层先制止护场投射器，再隔离两个本地供给选择器，两者放好后查本层当前指示。这建立到机组大厅安全通行，没有完成大厅独立支路核验、停用两续启组件或批准受控停止。改变对象配置，使该对象原检查失效。")])
material("RF-QF03-R-ISOLATION","继电层供给选择器","Q-F03","procedure","RF-S05.isolator","rf-relay-layer-isolation-plate",[
("Place ISO-L and ISO-R in their isolated positions, then inspect the current revision at the separate check stand. They control the corridor feed for this layer. Reconnecting either selector cancels the corridor isolation check until it is performed again. A preserved earlier check remains a historical record but cannot authorise entry under a changed configuration. The internal renewal relays are different components in the next hall.","将ISO-L/R置隔离位，再在独立检查站核当前版本。它们控制本层通道供给。任一重连会取消通道隔离有效检查，须重查；旧检查仍是历史记录，不能许可变配置后进入。内部续启继电器是下一厅另两组件。")])
material("RF-QF03-R-LINK","第一段：隔离左右支路","Q-F03","procedure","RF-S06.link","rf-machine-link-service-original",[
("The forced-link stage shields the central progress meter until both branches are isolated and the current configuration is verified. The left branch stand is front-left; the right branch is front-right. Verification belongs to the rear-left station. Operations cost one action point each. You may isolate left or right first. Reconnecting a branch changes the revision and cancels the old verification.","强制联络段在两支路隔离且当前配置核验前锁护中央进度。左支路站为前左，右为前右，核验为后左。每项1AP，左右先后可换。重连支路改变版本，撤销旧核验。"),
("After the verified link work, control can reduce resistance to seventy per cent of this encounter's actual starting capacity. Any excess in that action is discarded at this boundary. The phase changes only at the complete action's end. Existing damaging intentions are replaced by a visible non-damaging recalibration, and two finite renewal components are scheduled for the next round. They do not act immediately in this decision slot.","联络工作核验后，可将抵抗降到本次实际起始容量70%。此动作超出边界部分舍弃，仅完整动作末切段。旧伤害意图换为可见无伤害重校准，两有限续启组件排到下一轮，不在当前决策槽立刻行动。")])
material("RF-QF03-R-RENEWAL","第二段：两组件、旁路锁与当前核验","Q-F03","procedure","RF-S06.renewal","rf-machine-renewal-service-original",[
("The renewal phase has exactly two declared relay components. Each has its own resistance meter and next-round arrival. Control both actual components before latching the bypass from front-left. Then verify the current bypass revision from rear-left. A finite schedule is not a completed relay result, and a component that has not arrived cannot be reported stopped. No extra component replaces an already declared participant.","续启段恰有两台声明组件，各有抵抗计量并在下一轮加入。先制止两实体，再由前左扣旁路锁，后左核当前版本。有限排程不是组件完成结果，未到场组件不能报告停用。没有新组件替代已声明参与者。"),
("Before that work is complete, attacks may reduce central resistance only to thirty-five per cent of the actual starting capacity. The boundary is visible. If resistance is already at the boundary, completing the current verification changes the phase at that action's end; an empty extra attack is unnecessary. Releasing the bypass invalidates its old check. The ordinary stop request is still insufficient here.","工作齐备前，攻击只能降中央抵抗到实际起始容量35%，边界可见。若已到边界，补齐当前核验即在动作末切段，无需再空打一拳。放开旁路会使旧检查失效。此段普通停止请求仍不足。")])
material("RF-QF03-R-DAMPING","第三段：核验后批准受控停止","Q-F03","procedure","RF-S06.damping","rf-machine-damping-service-original",[
("Set the damping arrangement from front-right and verify its current revision from rear-left. Front-left then approves controlled stop for that same verified arrangement. Approval does not change the configuration it approves. Changing damping afterwards does change the configuration and cancels both check and approval. The earlier check remains visible as history, rather than becoming a current authority.","由前右设置阻尼，后左核当前版本，前左随后批准同一已核配置的受控停止。批准不会改它批准的配置。之后改阻尼则改变配置，同时撤销检查和批准。旧检查作为历史可见，没有变成当前权限。"),
("Until ready, the machine retains at least one unit of resistance. If one remains when controlled stop is approved, that operation can safely conclude the encounter; do not strike the facility merely to satisfy an empty attack requirement. A safe-stop receipt states that automatic restart is disabled and the dangerous programme is stable. It leaves the policy decision to the dispatch desk.","未就绪时机组至少留1抵抗。批准时若仅剩1，该操作即可安全收束，不要为满足空攻击要求打设施。安全停止回执说明自动续启禁用、危险程序稳定，政策方向留给调度台。")])
material("RF-QF03-R-CLOCK","同一尝试的资源与暂停","Q-F03","short_notice","RF-S06.clock","rf-machine-attempt-boundary-notice",[
("All three internal phases share this attempt's life, focus, action points, carried supplies, aid allotment, cooldowns, relic uses and placed devices. A phase transition replenishes none of them. Reading, writing, translation, clarification and actual audio playback pause the plan slots, without providing recovery or executing a queued click on return. Withdrawing retries the whole declared encounter entry, not a free refill between phases.","三内部阶段共用本次生命、专注、AP、携带补给、配发、冷却、遗物次数和放置装置。切段没有补满。阅读、写作、翻译、澄清与实际播放音轨暂停计划槽，不提供恢复，也不在返回时补执行排队点击。撤退重试整个声明入口，没有内部阶段免费回满。")])
material("RF-QF03-L-OPERATOR","机组检修说明脚本","Q-F03","listening_script","RF-S06.operator","rf-machine-local-service-record",[
("Service record: A stop request by itself did not prevent reconnection. We marked the left and right forced-link branches, the finite renewal components and the damping check as separate objects. First isolate both forced-link branches and verify the current configuration. Either branch may be isolated first. Before verification, force against the main resistance meter has no effect. Do not interpret this as an instruction to attack a different, unlabelled facility.","检修记录：单独停止请求没有阻止重连。我们分别标明左右强制联络支路、有限续启组件与阻尼检查。先隔离两支路并核当前配置，左右先后可换。核验前对主抵抗计量施力无效，不能据此攻击另一未标设施。"),
("At the first boundary, the full action ends before the next stage begins. The old damaging intention becomes a visible recalibration with no damage. Two renewal components can arrive in the next round. When they are actually stopped, latch the bypass and verify it. If you have already reached the second boundary, that verification is enough to move on. Excess force is not stored for the next phase. These stages preserve the same party resources and temporary devices.","首边界在完整动作结束后进入下一段，旧伤害意图成为可见无伤害重校准。两续启组件下一轮可到场。实际停用后扣旁路锁并核验，若已达第二边界，这次核验便可推进。超量施力没有留给下一段。各段保留同一队伍资源与临时装置。"),
("Finally, set damping, verify the revision and approve controlled stop. Approval preserves the check because it approves that configuration; an actual subsequent change cancels it. The machine's resistance is not a measure of how much of the tower to demolish. After safe stop, the dispatch desk can present the prepared choices without battle pressure. The record does not choose among them. This script must be read as a transcript unless its actual candidate audio is separately played.","最后设置阻尼、核版本并批准受控停止。批准同一配置所以保留检查，后续实际改变才撤销。抵抗不衡量应拆掉多少塔。安全停止后，调度台可无战斗压力显示准备好的选择，记录没有替你选。这份脚本是书面稿，除非另行实际播放候选音轨。")])
material("RF-QF04-R-OPTIONS","最后的命令：三个可执行方向","Q-F04","extended_reading","RF-S07.policies","rf-public-final-policy-explanation",[
("Stopping the dangerous programme gives room for a decision; it does not make the decision for you. The sealed preparation keeps six distinct towers and their actual duties, supplies and local preservation records. Central and island arrangements share those base requirements. The distributed arrangement also needs the verified technical package, six actual enhanced installations, transition supplies, a common protocol accepted by the relevant operators and district representatives, and current field trials. A report describing an item is not its completion receipt.","停止危险程序给决策空间，没有替你决策。封存准备保留六座独立塔及实际岗位、供给和本地保全。中央与孤网共需基础条件，分布还需验证技术包、六塔实际增强安装、过渡供给、实际操作方和地区代表接受的共同协议，以及当前现场试运行。描述某项的报告不是完成回执。"),
("Restricted central coordination retains cross-region balancing and much of the existing transport capacity. It can help a weaker district through a difficult period without requiring immediate full conversion. It must retain a checked limit, disable unlimited renewal and identify continuing supervision. Some services will still be rationed, and the old equipment requires maintenance. Concentrated authority remains a practical risk. A new person at the desk does not by itself prevent the next temporary exception from becoming permanent.","受限中央协调保留跨区调峰及较多现有运输能力，可使较弱地区渡过困难，不要求立刻全转换。须保受检上限、禁无限续启并明确持续监督。仍需轮流限供，旧设备也需维护，集权仍有现实风险。换一位值守，不能自行阻止下次临时例外变永久。"),
("An orderly island arrangement removes central forced dispatch and the main cross-region links according to the prepared sequence. It preserves local protection and duty rather than demolishing towers or switching off every supply. Local operators gain more direct control over the limits they accept. The cost is less cross-region balancing and some lost assistance. Certain protection areas may shrink, outer residents may need relocation and shipping may become more expensive. Independence for a wealthy district does not automatically provide resources to a poorer one.","有序孤网按准备顺序解除中央强制调度与主要跨区联络，保本地保护及值守，而非拆塔或关闭所有供给。地区操作方更直接决定可承受上限。代价为减少跨区调峰与部分互助，有的保护范围收缩，外缘住民需安置，航运成本上升。富裕地区独立不会自动给贫弱地区资源。"),
("A distributed arrangement keeps bounded assistance while placing local control, fault isolation and shared review under the accepted protocol. It uses the actual enhanced equipment and trained duties through the verified transition. The seventh tower becomes a constrained hub rather than an unlimited command source. This preparation is expensive and can temporarily reduce service during changeover. Maintenance, standards and disputes continue to require cooperation. A passed field trial supports its stated conditions, not a promise that every later failure has been removed.","分布安排在已接受协议下结合本地控制、故障隔离和共同复核，保留有限互助。转换使用实际增强设备与受训岗位，第七塔成为受约束枢纽，而非无限命令源。准备成本高，切换暂减部分服务，维护、标准及争议仍需合作。试运行支持声明条件，没有承诺今后永无失败。"),
("The option display must name each missing qualification now, using the sealed version and current physical safety. Choosing a preferred description does not install a device or make a different protocol current. If the distributed work is incomplete, central and island remain legitimate prepared decisions when the base and central safety conditions hold. Revisiting the protected pre-final adventure later may produce another result, but it cannot change the ending snapshot that has already been committed.","方案显示应按封存版本和当前实体安全列出每个缺项。选择偏好说明不会安装装置，也不会使另一协议成为当前。分布工作未齐时，只要基础及中央安全成立，中央与孤网仍是正当准备方向。后来回访终局前冒险可另产结果，不能改已提交结局快照。"),
("Historical responsibility remains attached to the reviewed actions. Retaining coordination does not erase Voss's responsibility, and a distributed preference does not excuse a missing supply or unsafe operation. Rook's custody is not a replacement for the old-capital review. Keep the provenance and access limits of earlier records. A private name or an uncompleted companion reconciliation cannot be added to the public account merely to make an ending scene more satisfying.","历史责任仍附已审行为。保协调不会抹去沃斯责任，偏好分布也不会使缺供给或危险操作免责。鲁克看管不替代旧都审查。保留较早记录来源与范围，不能只为尾声更圆满就向公共档案添私人身份或未完成同伴和解。"),
("Your short final instruction should identify the chosen prepared direction and acknowledge its operating boundary. You may write freely and then explicitly confirm the action that the system proposes. A structured fallback is available when language interpretation is uncertain or unavailable. It records a deliberate choice while leaving the writing assessment pending. Word count, subtitles, translation, hints, companions, combat difficulty and political vocabulary do not add or remove a technical qualification.","最后短指令须明确准备好的方向及运行边界。可自由写后逐项确认系统呈现的动作，语言解释不确定或不可用时有结构化后备。它记录明确选择，写作评价仍待审。字数、字幕、翻译、提示、同伴、战斗难度或政治用词都不会增减技术资格。"),
("The mist was present before the present overload. Reducing extraction and preventing dangerous forced renewal will not clear the sea at once or remove accumulated damage. Six months is a limited follow-up window, with different benefits, costs and continuing duties under each decision. The result can show whether people have kept records, supplied a shift and managed a fault. It cannot certify permanent recovery or a learner's English ability simply because the final command has been executed.","雾原在本轮超载前已存在。降抽取、防危险强制续启，不会立刻清雾或消除累积损伤。六个月是有限跟进窗，各方向所得、代价及持续岗位不同。结果可显示人们是否保记录、供班次、管故障，不能因最后命令执行便认证永久恢复或学习者英语能力。")])
material("RF-QF04-R-COMMAND","调度台短指令与确认","Q-F04","short_notice","RF-S07.control","rf-dispatch-final-instruction-notice",[
("State the direction you intend to execute: restricted central coordination, orderly island operation, or the prepared distributed arrangement. Retain the checked operating boundaries and public responsibility record. Review the current qualification display and explicit action preview before confirming. Cancelling a preview returns to the same draft and world state. An unclear sentence may be clarified without reopening completed combat.","明确要执行方向：受限中央协调、有序孤网或已准备分布安排，保受检运行边界与公共责任记录。确认前读当前资格及明确动作预览。取消预览回到同一草稿和世界。句子不清楚可澄清，无需重打已完成战斗。")])
material("RF-QF04-L-DISPATCH","最后提交前的值守核对脚本","Q-F04","listening_script","RF-S07.dispatch","rf-dispatch-confirmation-desk-exchange",[
("Dispatch officer: The dangerous programme has a current safe-stop receipt, and this desk now has the actual decision-node permission. We will show the sealed preparation and every missing qualification before you choose. Restricted central and orderly island arrangements depend on base preservation and current safety. Distribution needs the additional actual work that has been visible since the glass city. A statement of support cannot complete that work.","调度值守：危险程序有当前安全停止回执，此台也已有实际决策节点许可。选择前显示封存准备及每项缺项。受限中央与有序孤网需基础保全和当前安全，分布需学城起已公开的额外实体工作，表态支持不能完成工作。"),
("Visitor: My short instruction identifies a direction, not a claim that the mist will disappear. I want to see the proposed action and its limits before committing it. If the system cannot reliably interpret my wording, I will confirm the structured action explicitly. That assistance should not be recorded as an assessed free-writing result. Dispatch officer: The preview is read-only. Closing it does not consume the sealed resources or issue another reward.","访客：短指令明确方向，没有声称雾会消失。提交前我要看拟执行动作及限制。系统不能可靠解释措辞时，我逐项确认结构化动作，该辅助不能登记为已评价自由写作。值守：预览只读，关闭不会消耗封存资源或发另一奖励。"),
("Dispatch officer: On confirmation, we commit the actual decision and an ending snapshot together. Later presentations read that snapshot rather than rewriting the six districts. A six-month card is a bounded account, not a guarantee. Earlier responsibility and the natural mist remain part of the result. You may skip the presentation without losing the committed ending, and you are not required to write another long essay to finish. Companion letters must match what actually happened in their own stories.","调度值守：确认把实际决定与结局快照一同提交，后续表现读快照，没有重写六地。六个月卡是有限记录，并非保证。较早责任与自然雾仍在结果中。可跳过表现而不丢已提交结局，不需另写长作文才算完成。同伴信件必须符合各自实际故事。")])
material("RF-QF05-R-AFTER","六个月后的阶段性记录","Q-F05","short_notice","RF-S07.epilogue","rf-ending-presentation-method",[
("The immediate action, six regional follow-up cards, compatible companion notes and public archive account read the committed ending snapshot. A companion who did not join, or whose private work was not completed, receives only a note compatible with the recorded facts. It does not invent a reunion or disclose a private identity. The archive keeps responsibility and current access limits under every direction.","即时动作、六地区跟进卡、兼容同伴近况和公共档案读已提交快照。未招募或私人工作未完成的同伴，仅显示符合记录事实的近况，不编团聚或公开私人身份。各方向均保留责任和当前访问范围。"),
("This is a six-month stage of continuing work. Natural mist remains. You may review your actual learning record or enter an optional later verification task when one is genuinely produced. Neither is a new compulsory puzzle, an extra ending reward, or proof that your English has reached a particular level. Continuing from a clearly labelled pre-final adventure belongs to another result branch.","这是持续工作中的六个月阶段，自然雾仍在。可看真实学习记录，或在后续验证实际制作后进入可选复核；两者均不是新强制谜题、额外结局奖励，也不证明英语达某等级。明确标记的终局前冒险继续属于另一个结果分支。")])

