edges=[("RF-S01","RF-S02","formal_recognised"),("RF-S01","RF-S03","basic_maintenance"),("RF-S02","RF-S04","formal_released"),("RF-S03","RF-S04","shaft_safe"),("RF-S04","RF-S05","command_released"),("RF-S05","RF-S06","current_isolation"),("RF-S06","RF-S07","central_stable")]
