for scene,ss in spots.items():
    ports=[]
    for a,b,gate in edges:
        if scene not in (a,b):continue
        target=b if scene==a else a
        ports.append(dict(id=scene+".to-"+target,target_scene=target,target_port=target+".to-"+scene,stand=point(*portcoords[len(ports)]),gate=gate))
    encounter={"RF-S03":"ENC-RF-01","RF-S04":"ENC-RF-02","RF-S05":"ENC-RF-03","RF-S06":"ENC-RF-04"}.get(scene)
    danger=[] if not encounter else [dict(id=encounter+".danger",area=dict(left=70,top=74,right=94,bottom=94),active_until_receipt="RF:"+encounter+":result")]
    scenes.append(dict(id=scene,walk=dict(left=5,top=20,right=95,bottom=95),blocked=[dict(left=44,top=45,right=56,bottom=55)],danger=danger,ports=ports,spots=[dict(id=scene+"."+sid,stand=point(x,y),purpose_zh=p) for sid,x,y,p in ss],geometry_status="original_graybox_unreviewed",visual_and_collision_review="human_pending"))

